namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }
    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Description = "A simple yet delicious pizza with fresh tomatoes, mozzarella, and basil.",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps = ["Preheat oven to 475°F (245°C).", "Roll out dough on a floured surface.", "Spread crushed tomatoes over dough.", "Tear mozzarella and distribute evenly.", "Bake for 10-12 minutes until crust is golden.", "Top with fresh basil and a drizzle of olive oil."],
                TotalRatings = 12, RatingSum = 50
            },
            new Recipe
            {
                Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
                Description = "Tender chicken pieces in a creamy, spiced tomato sauce.",
                Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger", "Cumin", "Turmeric"],
                Steps = ["Marinate chicken in yogurt and spices for 1 hour.", "Grill or pan-fry chicken until charred.", "Sauté onion, garlic, and ginger.", "Add tomato sauce and spices, simmer 15 min.", "Stir in cream and cooked chicken.", "Simmer 10 minutes and serve with rice."],
                TotalRatings = 8, RatingSum = 35
            },
            new Recipe
            {
                Id = 3, Title = "Spaghetti Carbonara", Category = "Italian",
                Description = "A Roman classic with eggs, cheese, pancetta, and black pepper.",
                Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Pecorino Romano", "Black pepper", "Salt"],
                Steps = ["Cook spaghetti in salted boiling water.", "Fry pancetta until crispy.", "Whisk eggs with grated pecorino and pepper.", "Drain pasta, reserving some water.", "Toss hot pasta with pancetta off heat.", "Quickly stir in egg mixture, adding pasta water as needed."],
                TotalRatings = 15, RatingSum = 68
            },
            new Recipe
            {
                Id = 4, Title = "Beef Tacos", Category = "Mexican",
                Description = "Seasoned ground beef in corn tortillas with fresh toppings.",
                Ingredients = ["Ground beef", "Corn tortillas", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Chili powder", "Cumin", "Onion"],
                Steps = ["Brown ground beef with diced onion.", "Add chili powder, cumin, salt, and pepper.", "Warm tortillas in a dry skillet.", "Fill tortillas with seasoned beef.", "Top with lettuce, tomato, cheese, and sour cream.", "Serve with lime wedges."],
                TotalRatings = 10, RatingSum = 42
            },
            new Recipe
            {
                Id = 5, Title = "Pad Thai", Category = "Thai",
                Description = "Stir-fried rice noodles with shrimp, peanuts, and tamarind sauce.",
                Ingredients = ["Rice noodles", "Shrimp", "Eggs", "Bean sprouts", "Green onions", "Peanuts", "Tamarind paste", "Fish sauce", "Sugar", "Lime"],
                Steps = ["Soak rice noodles in warm water for 30 min.", "Mix tamarind paste, fish sauce, and sugar for sauce.", "Stir-fry shrimp until pink, set aside.", "Scramble eggs in the wok.", "Add drained noodles and sauce, toss to coat.", "Add shrimp, bean sprouts, and peanuts. Serve with lime."],
                TotalRatings = 6, RatingSum = 27
            },
            new Recipe
            {
                Id = 6, Title = "Guacamole", Category = "Mexican",
                Description = "Fresh and creamy avocado dip with lime and cilantro.",
                Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Tomato", "Salt"],
                Steps = ["Halve and pit avocados, scoop into bowl.", "Mash with a fork to desired consistency.", "Stir in diced onion, jalapeño, and tomato.", "Add lime juice and chopped cilantro.", "Season with salt to taste.", "Serve immediately with tortilla chips."],
                TotalRatings = 9, RatingSum = 40
            },
            new Recipe
            {
                Id = 7, Title = "Green Curry", Category = "Thai",
                Description = "Fragrant coconut curry with vegetables and Thai basil.",
                Ingredients = ["Green curry paste", "Coconut milk", "Chicken or tofu", "Bamboo shoots", "Thai basil", "Fish sauce", "Sugar", "Bell pepper", "Eggplant"],
                Steps = ["Heat coconut cream in a pot until oil separates.", "Fry curry paste for 2 minutes until fragrant.", "Add protein and cook through.", "Pour in coconut milk, add vegetables.", "Season with fish sauce and sugar.", "Simmer 10 min, finish with Thai basil."],
                TotalRatings = 5, RatingSum = 22
            },
            new Recipe
            {
                Id = 8, Title = "Butter Chicken", Category = "Indian",
                Description = "Rich and creamy tomato-based chicken curry.",
                Ingredients = ["Chicken thighs", "Butter", "Tomato purée", "Heavy cream", "Garam masala", "Kashmiri chili", "Garlic", "Ginger", "Fenugreek leaves"],
                Steps = ["Marinate chicken in yogurt and spices.", "Grill or broil chicken until lightly charred.", "Melt butter, sauté garlic and ginger.", "Add tomato purée and spices, cook 15 min.", "Add cream and fenugreek, simmer 5 min.", "Add chicken, simmer until heated through."],
                TotalRatings = 11, RatingSum = 49
            },
        ];
        _nextId = _recipes.Count + 1;
    }

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().Order().ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }

    public void AddRecipe(RecipeSubmission submission)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = submission.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
        });
    }
}

@page "/recipes/{Category}"
@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService RecipeService

<PageTitle>@Category Recipes - RecipeHub</PageTitle>

<h1>@Category Recipes</h1>

@if (_recipes.Count == 0)
{
    <p class="text-muted">No recipes found in this category.</p>
}
else
{
    <div class="row">
        @foreach (var recipe in _recipes)
        {
            <div class="col-md-6 col-lg-4 mb-4">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">@recipe.Description</p>
                        <div class="mb-2">
                            <span class="text-warning">@GetStarDisplay(recipe.AverageRating)</span>
                            <small class="text-muted">(@recipe.TotalRatings ratings)</small>
                        </div>
                        <a href="/recipe/@recipe.Id" class="btn btn-outline-primary btn-sm">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

<a href="/" class="btn btn-link">← Back to Categories</a>

@code {
    [Parameter] public string Category { get; set; } = string.Empty;

    private IReadOnlyList<Recipe> _recipes = [];

    protected override void OnParametersSet()
    {
        _recipes = RecipeService.GetByCategory(Category);
    }

    private static string GetStarDisplay(double rating)
    {
        int full = (int)Math.Round(rating);
        return new string('★', full) + new string('☆', 5 - full);
    }
}

@page "/recipe/{Id:int}"
@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService RecipeService

@if (_recipe is null)
{
    <PageTitle>Recipe Not Found - RecipeHub</PageTitle>
    <h1>Recipe Not Found</h1>
    <p>The recipe you're looking for doesn't exist.</p>
    <a href="/" class="btn btn-link">← Back to Home</a>
}
else
{
    <PageTitle>@_recipe.Title - RecipeHub</PageTitle>

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/recipes/@_recipe.Category">@_recipe.Category</a></li>
            <li class="breadcrumb-item active">@_recipe.Title</li>
        </ol>
    </nav>

    <h1>@_recipe.Title</h1>
    <p class="lead text-muted">@_recipe.Description</p>

    <StarRating RecipeId="_recipe.Id" />

    <div class="row mt-4">
        <div class="col-md-4">
            <div class="card">
                <div class="card-header"><h5 class="mb-0">🧾 Ingredients</h5></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in _recipe.Ingredients)
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>
        <div class="col-md-8">
            <h5>📝 Instructions</h5>
            <ol class="list-group list-group-numbered mb-4">
                @foreach (var step in _recipe.Steps)
                {
                    <li class="list-group-item">@step</li>
                }
            </ol>
        </div>
    </div>

    <a href="/recipes/@_recipe.Category" class="btn btn-link mt-3">← Back to @_recipe.Category Recipes</a>
}

@code {
    [Parameter] public int Id { get; set; }

    private Recipe? _recipe;

    protected override void OnParametersSet()
    {
        _recipe = RecipeService.GetById(Id);
    }
}

@using RecipeHub.Services
@rendermode InteractiveServer
@inject RecipeService RecipeService

<div class="d-inline-flex align-items-center gap-2 my-2">
    <span class="fs-4">
        @for (int i = 1; i <= 5; i++)
        {
            int star = i;
            <span role="button"
                  style="cursor:pointer; color: @(star <= (_hovered > 0 ? _hovered : _selected) ? "#ffc107" : "#dee2e6")"
                  @onclick="() => SubmitRating(star)"
                  @onmouseover="() => _hovered = star"
                  @onmouseout="() => _hovered = 0"
                  title="Rate @star star@(star > 1 ? "s" : "")">★</span>
        }
    </span>
    @if (_submitted)
    {
        <span class="badge bg-success">Thanks for rating!</span>
    }
    else
    {
        <small class="text-muted">Click to rate</small>
    }
    @if (_recipe is not null)
    {
        <small class="text-muted ms-2">
            Avg: @_recipe.AverageRating.ToString("F1") (@_recipe.TotalRatings ratings)
        </small>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }

    private Models.Recipe? _recipe;
    private int _selected;
    private int _hovered;
    private bool _submitted;

    protected override void OnParametersSet()
    {
        _recipe = RecipeService.GetById(RecipeId);
    }

    private void SubmitRating(int stars)
    {
        if (_submitted) return;
        _selected = stars;
        RecipeService.AddRating(RecipeId, stars);
        _recipe = RecipeService.GetById(RecipeId);
        _submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe - RecipeHub</PageTitle>

<h1>Submit a Recipe</h1>
<p class="text-muted">Share your favorite recipe with the community!</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4>Recipe submitted!</h4>
        <p>Your recipe "<strong>@_model.Title</strong>" has been added.</p>
        <a href="/recipes/@_model.Category" class="btn btn-primary btn-sm">View in @_model.Category</a>
        <button class="btn btn-outline-secondary btn-sm ms-2" @onclick="Reset">Submit Another</button>
    </div>
}
else
{
    <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="submit-recipe" class="mb-4">
        <DataAnnotationsValidator />

        <div class="mb-3">
            <label class="form-label" for="title">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="_model.Title" placeholder="e.g., Grandma's Apple Pie" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="category">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="_model.Category">
                <option value="">-- Select a category --</option>
                @foreach (var cat in _categories)
                {
                    <option value="@cat">@cat</option>
                }
                <option value="Other">Other</option>
            </InputSelect>
        </div>

        <div class="mb-3">
            <label class="form-label" for="ingredients">Ingredients</label>
            <InputTextArea id="ingredients" class="form-control" rows="6" @bind-Value="_model.Ingredients"
                           placeholder="One ingredient per line&#10;e.g.,&#10;2 cups flour&#10;1 cup sugar&#10;3 eggs" />
            <div class="form-text">Enter one ingredient per line.</div>
        </div>

        <div class="mb-3">
            <label class="form-label" for="steps">Steps</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="_model.Steps"
                           placeholder="One step per line&#10;e.g.,&#10;Preheat oven to 350°F&#10;Mix dry ingredients&#10;Add wet ingredients" />
            <div class="form-text">Enter one step per line.</div>
        </div>

        <button type="submit" class="btn btn-primary"
                disabled="@(string.IsNullOrWhiteSpace(_model.Title) || string.IsNullOrWhiteSpace(_model.Category) || string.IsNullOrWhiteSpace(_model.Ingredients) || string.IsNullOrWhiteSpace(_model.Steps))">
            Submit Recipe
        </button>
    </EditForm>
}

@code {
    private RecipeSubmission _model = new();
    private IReadOnlyList<string> _categories = [];
    private bool _submitted;

    protected override void OnInitialized()
    {
        _categories = RecipeService.GetCategories();
    }

    private void HandleSubmit()
    {
        RecipeService.AddRecipe(_model);
        _submitted = true;
    }

    private void Reset()
    {
        _model = new();
        _submitted = false;
    }
}

