                  style="cursor:pointer; color: @(star <= (_hovered > 0 ? _hovered : _selected) ? "#ffc107" : "#dee2e6")"
                  @onclick="() => SubmitRating(star)"
                  @onmouseover="() => _hovered = star"
                  @onmouseout="() => _hovered = 0"
                  title="Rate @star star@(star > 1 ? "s" : "")">★</span>
