using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Description = "A simple yet delicious pizza with fresh tomatoes, mozzarella, and basil.",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps = ["Preheat oven to 475°F (245°C).", "Roll out dough on a floured surface.", "Spread crushed tomatoes over dough.", "Tear mozzarella and distribute evenly.", "Bake for 10-12 minutes until crust is golden.", "Top with fresh basil and a drizzle of olive oil."],
                TotalRatings = 12, RatingSum = 50
            },
            new Recipe
            {
                Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
                Description = "Tender chicken pieces in a creamy, spiced tomato sauce.",
                Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger", "Cumin", "Turmeric"],
                Steps = ["Marinate chicken in yogurt and spices for 1 hour.", "Grill or pan-fry chicken until charred.", "Sauté onion, garlic, and ginger.", "Add tomato sauce and spices, simmer 15 min.", "Stir in cream and cooked chicken.", "Simmer 10 minutes and serve with rice."],
                TotalRatings = 8, RatingSum = 35
            },
            new Recipe
            {
                Id = 3, Title = "Spaghetti Carbonara", Category = "Italian",
                Description = "A Roman classic with eggs, cheese, pancetta, and black pepper.",
                Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Pecorino Romano", "Black pepper", "Salt"],
                Steps = ["Cook spaghetti in salted boiling water.", "Fry pancetta until crispy.", "Whisk eggs with grated pecorino and pepper.", "Drain pasta, reserving some water.", "Toss hot pasta with pancetta off heat.", "Quickly stir in egg mixture, adding pasta water as needed."],
                TotalRatings = 15, RatingSum = 68
            },
            new Recipe
            {
                Id = 4, Title = "Beef Tacos", Category = "Mexican",
                Description = "Seasoned ground beef in corn tortillas with fresh toppings.",
                Ingredients = ["Ground beef", "Corn tortillas", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Chili powder", "Cumin", "Onion"],
                Steps = ["Brown ground beef with diced onion.", "Add chili powder, cumin, salt, and pepper.", "Warm tortillas in a dry skillet.", "Fill tortillas with seasoned beef.", "Top with lettuce, tomato, cheese, and sour cream.", "Serve with lime wedges."],
                TotalRatings = 10, RatingSum = 42
            },
            new Recipe
            {
                Id = 5, Title = "Pad Thai", Category = "Thai",
                Description = "Stir-fried rice noodles with shrimp, peanuts, and tamarind sauce.",
                Ingredients = ["Rice noodles", "Shrimp", "Eggs", "Bean sprouts", "Green onions", "Peanuts", "Tamarind paste", "Fish sauce", "Sugar", "Lime"],
                Steps = ["Soak rice noodles in warm water for 30 min.", "Mix tamarind paste, fish sauce, and sugar for sauce.", "Stir-fry shrimp until pink, set aside.", "Scramble eggs in the wok.", "Add drained noodles and sauce, toss to coat.", "Add shrimp, bean sprouts, and peanuts. Serve with lime."],
                TotalRatings = 6, RatingSum = 27
            },
            new Recipe
            {
                Id = 6, Title = "Guacamole", Category = "Mexican",
                Description = "Fresh and creamy avocado dip with lime and cilantro.",
                Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Tomato", "Salt"],
                Steps = ["Halve and pit avocados, scoop into bowl.", "Mash with a fork to desired consistency.", "Stir in diced onion, jalapeño, and tomato.", "Add lime juice and chopped cilantro.", "Season with salt to taste.", "Serve immediately with tortilla chips."],
                TotalRatings = 9, RatingSum = 40
            },
            new Recipe
            {
                Id = 7, Title = "Green Curry", Category = "Thai",
                Description = "Fragrant coconut curry with vegetables and Thai basil.",
                Ingredients = ["Green curry paste", "Coconut milk", "Chicken or tofu", "Bamboo shoots", "Thai basil", "Fish sauce", "Sugar", "Bell pepper", "Eggplant"],
                Steps = ["Heat coconut cream in a pot until oil separates.", "Fry curry paste for 2 minutes until fragrant.", "Add protein and cook through.", "Pour in coconut milk, add vegetables.", "Season with fish sauce and sugar.", "Simmer 10 min, finish with Thai basil."],
                TotalRatings = 5, RatingSum = 22
            },
            new Recipe
            {
                Id = 8, Title = "Butter Chicken", Category = "Indian",
                Description = "Rich and creamy tomato-based chicken curry.",
                Ingredients = ["Chicken thighs", "Butter", "Tomato purée", "Heavy cream", "Garam masala", "Kashmiri chili", "Garlic", "Ginger", "Fenugreek leaves"],
                Steps = ["Marinate chicken in yogurt and spices.", "Grill or broil chicken until lightly charred.", "Melt butter, sauté garlic and ginger.", "Add tomato purée and spices, cook 15 min.", "Add cream and fenugreek, simmer 5 min.", "Add chicken, simmer until heated through."],
                TotalRatings = 11, RatingSum = 49
            },
        ];
        _nextId = _recipes.Count + 1;
    }

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().Order().ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }

    public void AddRecipe(RecipeSubmission submission)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = submission.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
        });
    }
}

namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }
    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

