<div class="text-center mb-5">
    <h1 class="display-4">🍳 RecipeHub</h1>
    <p class="lead text-muted">Discover and share delicious recipes from around the world</p>
</div>

<h2 class="mb-3">Browse by Category</h2>
<div class="row">
    @foreach (var category in _categories)
    {
        <div class="col-md-4 col-sm-6 mb-4">
            <a href="/recipes/@category" class="text-decoration-none">
                <div class="card h-100 shadow-sm border-0" style="transition: transform 0.2s;">
                    <div class="card-body text-center py-5">
                        <div class="display-6 mb-2">@GetCategoryEmoji(category)</div>
                        <h4 class="card-title text-dark">@category</h4>
                        <p class="card-text text-muted">@GetRecipeCount(category) recipes</p>
                    </div>
                </div>
            </a>
        </div>
    }
</div>

<div class="text-center mt-4">
    <p class="text-muted">Have a recipe to share?</p>
    <a href="/submit" class="btn btn-primary btn-lg">Submit a Recipe</a>
</div>

@code {
    private IReadOnlyList<string> _categories = [];

    protected override void OnInitialized()
    {
        _categories = RecipeService.GetCategories();
    }

    private int GetRecipeCount(string category) =>
        RecipeService.GetByCategory(category).Count;

    private static string GetCategoryEmoji(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Mexican" => "🌮",
        "Thai" => "🥘",
        _ => "🍽️"
    };
}

arguments.old_str:
using RecipeHub.Components;

var builder = WebApplication.CreateBuilder(args);

// Add services to the container.
builder.Services.AddRazorComponents()
    .AddInteractiveServerComponents();

arguments.new_str:
using RecipeHub.Components;
using RecipeHub.Services;

var builder = WebApplication.CreateBuilder(args);

// Add services to the container.
builder.Services.AddSingleton<RecipeService>();
builder.Services.AddRazorComponents()
    .AddInteractiveServerComponents();

